def transform(grid):
    g=[row[:] for row in grid]
    cols=[c for c in range(len(g[0])) if any(g[r][c] for r in range(12,15))]
    for c in cols:
        gaps=[]
        for r,row in enumerate(grid):
            if row[c]==0 and any(row[:c]) and any(row[c+1:]):
                left=next((row[k] for k in range(c-1,-1,-1) if row[k]),None)
                gaps.append((r,left))
        start=0
        for r,color in gaps:
            for rr in range(start,r+1): g[rr][c]=color
            start=r+1
    # complete the one-cell break in the top horizontal stroke
    if g[2][5] and g[2][7]==0: g[2][6]=g[2][5]
    return g
